const delta={type:'text_delta',delta:'x'};
const noopObserver={onResult(){}};
function streamBatch(stream,count){for(let i=0;i<count;i++){stream.push(delta);assert.equal(stream.queue.dequeue(),delta);}}
const plain=new EventStream(incomplete,identity),observed=new EventStream(incomplete,identity);
