 observeEffectiveDispatch(options,model,{transport:'sse',previousResponseMode:'none',instructionPrefix:context.systemPrompt,orderedToolDefinitions:[],orderedToolIdentifiers:[],cacheKey:'fixture',cacheRetention:'short',cachePolicy:{enabled:true},cacheBoundary:[]});
 stream.push({type:'done',reason:'stop',message:response()});stream.end();return stream;
}
