const counts={plain:1000000,observed:1000000,append:10000,request:200};
const cases={plain:()=>streamBatch(plain,counts.plain),observed:()=>streamBatch(observed,counts.observed),append:()=>appendBatch(counts.append),request:()=>requestBatch(counts.request)};
