 for(const [name,run] of Object.entries(cases)){
  for(let i=0;i<10;i++)await run();await collect();
  if(phase==='timing'){
   const samples=[];for(let i=0;i<30;i++){const start=performance.now();await run();samples.push((performance.now()-start)/counts[name]);}
   const sorted=[...samples].sort((a,b)=>a-b);results[name]={count:counts[name],samples,p50:sorted[15],p95:sorted[28]};
