   const inspector=new Session();inspector.connect();let profile;
   try{await inspector.post('HeapProfiler.startSampling',{samplingInterval:4096,includeObjectsCollectedByMajorGC:true,includeObjectsCollectedByMinorGC:true});for(let i=0;i<10;i++)await run();profile=(await inspector.post('HeapProfiler.stopSampling')).profile;}finally{inspector.disconnect();}
   const measured=allocation(profile);results[name]={count:counts[name]*10,bytesPerOperation:measured.bytes/(counts[name]*10),...measured};
  }
 }
